#!/usr/bin/env bash
# Print the DNS records outbound mail needs (A, SPF, DKIM, DMARC, reverse DNS) and
# check which are already published. Run on the server after `docker compose up`
# (the DKIM key is generated by the mail container on first start).
#
#   ./scripts/mail-dns.sh                      # detects the server's public IPv4
#   SERVER_IP=203.0.113.10 ./scripts/mail-dns.sh
#   DMARC_RUA=dmarc@techzaz.lk ./scripts/mail-dns.sh   # also ask for DMARC reports
set -euo pipefail
cd "$(dirname "$0")/.."

[[ -f .env ]] || { echo "No .env — run scripts/init-env.sh first." >&2; exit 1; }
env_get() { sed -n "s/^$1=//p" .env | tr -d '"'; }
DOMAIN="$(env_get MAIL_DOMAIN)"
HOST="$(env_get MAIL_HOSTNAME)"
SELECTOR=tems   # DKIM_SELECTOR in docker-compose.yml
IP="${SERVER_IP:-$(curl -4 -fsS --max-time 5 https://api.ipify.org || true)}"
[[ -n "$IP" ]] || { echo "Could not detect the public IP; set SERVER_IP." >&2; exit 1; }

# The image writes a BIND-style record; join its quoted chunks into one value.
DKIM="$(docker compose exec -T mail cat "/etc/opendkim/keys/${DOMAIN}.txt" 2>/dev/null \
  | grep -o '"[^"]*"' | tr -d '"\n' | sed 's/; */; /g' || true)"

DMARC="v=DMARC1; p=quarantine; adkim=s; aspf=s"
[[ -n "${DMARC_RUA:-}" ]] && DMARC="${DMARC}; rua=mailto:${DMARC_RUA}"
SPF="v=spf1 ip4:${IP} -all"

have() { command -v "$1" >/dev/null 2>&1; }
lookup() { # type name → published value(s), one line
  if [[ "$1" == PTR ]] && have dig; then dig +short -x "$2" | tr -d '\n'
  elif have dig; then dig +short "$1" "$2" | tr -d '"\n'
  elif have host; then host -t "$1" "$2" 2>/dev/null | sed -n 's/.* \(has address\|descriptive text\|domain name pointer\) //p' | tr -d '"\n'
  fi
}
row() { # type name expected matcher
  local got status
  got="$(lookup "$1" "$2")"
  if ! have dig && ! have host; then status="(install dig to check)"
  elif [[ -n "$got" && "$got" == *"$4"* ]]; then status="✓ published"
  elif [[ -n "$got" ]]; then status="✗ differs: ${got:0:60}"
  else status="✗ missing"; fi
  printf '%-6s %-36s %s\n       %s\n\n' "$1" "$2" "$status" "$3"
}

echo "Publish these records (server ${IP}):"
echo
row A   "$HOST"                        "$IP"    "$IP"
row A   "$DOMAIN"                      "$IP     (the console; Caddy needs it for the TLS certificate)" "$IP"
row TXT "$DOMAIN"                      "$SPF"   "v=spf1"
if [[ -n "$DKIM" ]]; then
  row TXT "${SELECTOR}._domainkey.${DOMAIN}" "$DKIM" "${DKIM: -24}"
else
  echo "TXT    ${SELECTOR}._domainkey.${DOMAIN}"
  echo "       (key not found — start the stack first: docker compose up -d mail)"
  echo
fi
row TXT "_dmarc.${DOMAIN}"             "$DMARC" "v=DMARC1"
row PTR "$IP"                          "$HOST   (set at your hosting provider, not in your DNS zone)" "$HOST"
echo "Also: the server must be allowed to send on outbound port 25 (many clouds block it by default)."
